extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve avviarsi senza errori"):
		return
	var player: CharacterBody3D = find_by_name(main, "Player") as CharacterBody3D
	if not check("player", player != null, "Nella scena serve un CharacterBody3D chiamato Player"):
		return
	var anim_tree: AnimationTree = player.get_node_or_null("AnimationTree") as AnimationTree
	if not check("tree", anim_tree != null, "Player deve avere un nodo figlio AnimationTree"):
		return

	var playback: AnimationNodeStateMachinePlayback = anim_tree.get("parameters/playback")
	if not check("playback", playback != null, "La State Machine dell'AnimationTree deve fornire il playback"):
		return

	player.global_position = Vector3(2.0, 2.0, -4.0)
	player.velocity = Vector3.ZERO
	await wait_physics_frames(10)
	check("ground_init", str(playback.get_current_node()) == "Ground", "Il personaggio a terra deve trovarsi nello stato 'Ground'")

	var walk_spd: float = get_prop(player, "walk_speed", 5.0)
	Input.action_press("move_forward")
	await wait_physics_frames(15)
	Input.action_release("move_forward")
	var blend_val = anim_tree.get("parameters/Ground/blend_position")
	check("blend_walk", blend_val != null and absf(float(blend_val) - walk_spd) < 0.8, "Il blend space Ground deve continuare ad aggiornarsi con la velocità")

	await tap_action("jump")
	await wait_physics_frames(4)
	check("jump_up", str(playback.get_current_node()) == "Jump" and player.velocity.y > 0.0, "Salendo nel salto lo stato deve essere 'Jump'")

	var reached_fall := false
	for i in range(45):
		await wait_physics_frames(1)
		if player.velocity.y < -0.2:
			if str(playback.get_current_node()) == "Fall":
				reached_fall = true
				break
	check("jump_fall", reached_fall, "Scendendo dal salto lo stato deve passare a 'Fall'")

	for i in range(50):
		await wait_physics_frames(1)
		if player.is_on_floor():
			break
	check("jump_land", str(playback.get_current_node()) == "Ground" and player.is_on_floor(), "Atterrando dal salto lo stato deve tornare a 'Ground'")

	player.global_position = Vector3(2.0, 6.0, -4.0)
	player.velocity = Vector3.ZERO
	await wait_physics_frames(8)
	check("edge_fall", str(playback.get_current_node()) == "Fall" and player.velocity.y < 0.0, "Cadendo a mezz'aria senza aver saltato lo stato deve passare direttamente a 'Fall'")

	for i in range(50):
		await wait_physics_frames(1)
		if player.is_on_floor():
			break
	check("edge_land", str(playback.get_current_node()) == "Ground" and player.is_on_floor(), "Dopo la caduta l'atterraggio deve ripristinare lo stato 'Ground'")

